body.script:
//
document.addEventListener('DOMContentLoaded', () => {
  // Sistema Dark Mode Blindado
  const setTheme = t => { 
    document.documentElement.setAttribute('data-bs-theme', t); 
    localStorage.setItem('theme', t); 
    const icon = document.querySelector('.btn-dark-mode i');
    if(icon) icon.className = t === 'dark' ? 'bi bi-sun-fill text-warning' : 'bi bi-moon-stars-fill';
  };
  const getTheme = () => localStorage.getItem('theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  setTheme(getTheme());

  document.querySelectorAll('.btn-dark-mode').forEach(btn => {
    btn.addEventListener('click', () => setTheme(document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark'));
  });

  // Animações de Scroll
  const obs = new IntersectionObserver(es => es.forEach(e => { if(e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); } }), {threshold: 0.1});
  document.querySelectorAll('.animate-up, .news-card').forEach((el, i) => {
    if(el.classList.contains('news-card')) el.style.transitionDelay = `${(i % 2) * 0.1}s`;
    el.classList.add('animate-up');
    obs.observe(el);
  });

  // Seta Voltar ao Topo
  const backToTopBtn = document.getElementById('backToTop');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 400) {
      backToTopBtn.classList.add('show');
    } else {
      backToTopBtn.classList.remove('show');
    }
  });

  backToTopBtn.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
});
//

//
document.addEventListener("DOMContentLoaded", function() {
    // Seleciona todas as imagens dentro do widget de postagens populares
    const popImages = document.querySelectorAll('.popular-posts .item-thumbnail img');

    popImages.forEach(img => {
        let src = img.getAttribute('src');
        if (src) {
            // Padrão 1: Substitui URLs antigas do Blogger (/s72-c/) por imagens com largura de 500px e altura de 350px com corte perfeito (-c)
            if (src.match(/\/s[0-9]+(\-c)?\//)) {
                img.setAttribute('src', src.replace(/\/s[0-9]+(\-c)?\//, '/w500-h350-c/'));
            } 
            // Padrão 2: Substitui URLs modernas do Blogger (/w72-h72-p.../) pela nossa resolução premium
            else if (src.match(/\/w[0-9]+\-h[0-9]+(.*?)\//)) {
                img.setAttribute('src', src.replace(/\/w[0-9]+\-h[0-9]+(.*?)\//, '/w500-h350-c/'));
            }
        }
    });
});
//
